package com.sirithree.shopops.admin.benchmark.v1.dataset.stage7b; import static org.assertj.core.api.Assertions.assertThat; import org.junit.jupiter.api.Test; import java.util.*;
class GovernanceScaleupGoldProofTest { @Test void everyNewRootHasPolicyProofFixedBeforeRuntime() throws Exception { Map<String,Object>d=Stage7BGovernanceDatasetSupport.objectResource("/benchmark/v1/governance/scaleup/governance-gold-proof.json"); @SuppressWarnings("unchecked") List<Map<String,Object>> roots=(List<Map<String,Object>>)d.get("roots"); assertThat(roots).hasSize(50); assertThat(roots).allSatisfy(x->{assertThat(x.get("goldDerivedBeforeRuntime")).isEqualTo(true); assertThat(x.get("runtimeOutputUsed")).isEqualTo(false);}); }}
